"""Execution formats and file interfaces: authored against v6.12."""
def register(topic,q,detail):
    topic('Shebang·Script Interpreter와 Argv 재구성','프로세스','fs/binfmt_script.c','load_script',
      '텍스트 script를 실행할 때 kernel이 script 문법을 해석하는 것이 아니라 interpreter 실행으로 연결하는 원리를 봅니다.',
      'Loader는 #!로 시작하는지 확인하고 고정 buffer 안에서 interpreter 경로와 optional argument를 찾습니다. Buffer가 항상 NUL 종료된다고 가정하지 않으며 경로 잘림은 ENOEXEC입니다. Exec 뒤 접근 불가능한 script는 ENOENT입니다. 기존 argv[0]을 제거하고 script 경로·optional argument·interpreter를 역순으로 copy하여 새 argv를 구성한 뒤 open_exec으로 interpreter file을 연결합니다.',
      '격리된 Linux에서 작은 #!/bin/sh script와 실행 인자를 비교하고 원본의 argc 증가·copy 순서를 적습니다. Shebang optional argument는 shell처럼 임의 개수의 단어로 나누는 parser가 아니며 PATH 검색이 아니라 지정 interpreter 경로를 사용하는 부분을 확인합니다.',
      'load_script의 next_terminator·PATH_INACCESSIBLE·remove_arg_zero·bprm->interpreter를 읽으세요.',
      q('Interpreter path가 buffer 끝에서 잘린 것으로 보이면 실행하는가?','ENOEXEC로 거부한다','잘린 경로를 무조건 실행한다','Loader는 newline 또는 경로 뒤 terminator가 없으면 truncated path로 판단합니다. Argument 잘림 허용과 interpreter 경로 잘림 거부는 다릅니다.'),
      q('Shebang loader가 script의 shell 문법을 직접 실행하는가?','Interpreter 실행으로 연결한다','Kernel 안에 shell parser가 들어 있다','open_exec(i_name)으로 interpreter를 열어 bprm->interpreter에 넣습니다. Script 문법의 해석은 해당 프로그램의 역할입니다.'),
      details=[detail('Stack copy 순서','실행 인자 저장 방향 때문에 script 경로, optional argument, interpreter 이름 순으로 copy합니다. 최종 argv 순서와 source 호출 순서가 반대로 보이는 이유를 추적하세요.'),detail('C String 범위','strnchr·buf_end·next_terminator는 bounded input을 다룹니다. char buffer를 항상 strlen으로 읽어도 된다는 가정을 피하는 실제 사례입니다.')])
    topic('Binfmt Misc·Format Handler와 Interpreter 수명','프로세스','fs/binfmt_misc.c','load_misc_binary',
      '외부 format이나 다른 architecture의 실행을 interpreter에 연결하는 kernel 등록 경로와 emulator 자체의 역할을 구분합니다.',
      'Loader는 user namespace의 binfmt_misc instance를 찾고 enabled 및 matching handler를 확인해 참조를 얻습니다. Preserve argv0, binary execfd, credential 및 이미 열린 interpreter 옵션에 따라 인자를 구성하고 interpreter file을 연결합니다. 모든 exit에서 handler 참조를 반환하여 동시 unregister와 수명을 맞춥니다. Kernel이 foreign instruction을 직접 emulation하는 함수는 아닙니다.',
      '격리된 namespace에서 이미 등록된 binfmt_misc 상태와 entry의 interpreter·flag를 조회합니다. Magic/mask 또는 extension의 matching과 emulator 동작을 분리하고, credential flag는 권한 선택에 영향을 주므로 실제 policy를 읽습니다.',
      'load_misc_binary·get/put_binfmt_handler·load_binfmt_misc를 읽으세요.',
      q('Handler를 찾은 뒤 users 참조가 필요한 이유는?','동시 제거 중 실행기가 객체를 계속 사용할 수 있게 한다','CPU instruction 종류를 늘리기 위해','get_binfmt_handler는 entries_lock 아래 refcount를 증가합니다. 끝의 put과 제거 후 최종 free를 연결해야 합니다.'),
      q('현재 user namespace에 instance가 없으면 항상 no handler인가?','조상 namespace instance를 찾는 경로가 있다','자기 namespace 밖은 어떤 경우에도 보지 않는다','load_binfmt_misc는 parent를 따라 올라갑니다. Namespace 이름만으로 모든 handler 조회가 완전히 독립이라고 가정하지 않습니다.'),
      details=[detail('열린 Interpreter','MISC_FMT_OPEN_FILE은 보관한 interpreter file을 file_clone_open으로 열고 아니면 open_exec 경로를 사용합니다. Path 문자열과 열린 file 객체의 수명·접근 가능성은 다릅니다.'),detail('Argv와 Credential','Preserve argv0는 기존 첫 인자 유지에, CREDENTIALS는 execfd_creds에 영향을 줍니다. 인자 표시 정책과 privilege 선택을 하나의 flag 의미로 묶지 않습니다.')])
    topic('BFLT·Flat Executable의 Stack과 NOMMU','프로세스','fs/binfmt_flat.c','load_flat_binary',
      '가상 메모리 page table을 쓰지 않는 구성에서도 executable data·인자·stack 배치를 준비하는 loader가 필요합니다.',
      'Flat loader는 library info를 초기화하고 argc/envc pointer 배열과 NOMMU argument 문자열 공간을 stack 길이에 포함한 뒤 alignment를 맞춥니다. load_flat_file 이후 library data pointer를 사용자 공간에 기록하고 MMU/NOMMU별 인자 stack을 준비합니다. Tables 생성과 platform register 초기화 후 finalize_exec 및 start_thread로 entry와 stack을 설정합니다.',
      '고정 v6.12의 CONFIG_MMU 분기를 비교하고 지원 architecture의 BFLT header·relocation 및 load_flat_file을 연결해 읽습니다. 일반 desktop에서 모든 flat file을 바로 실행할 수 있다고 가정하지 않고 kernel config와 executable ABI를 확인합니다.',
      'load_flat_binary의 stack_len·put_user·transfer_args_to_stack·start_thread를 읽으세요.',
      q('Argument stack 크기에 문자열만 포함하면 충분한가?','argv/envp pointer 배열도 포함해야 한다','pointer 배열은 언제나 0byte다','Source는 argc+1와 envc+1에 sizeof(char*)를 곱해 더합니다. 문자열 수가 많을 때 pointer 공간도 stack을 소비합니다.'),
      q('NOMMU branch도 setup_arg_pages만 동일하게 쓰는가?','transfer_args_to_stack과 별도 start_stack 배치를 사용한다','모든 config에서 같은 page table mapping만 실행한다','CONFIG_MMU 전처리 분기에 따라 stack 준비 경로가 갈립니다. 같은 함수 이름 아래 구성별 다른 메모리 모델을 읽습니다.'),
      details=[detail('User Memory 실패','Library data pointer 기록은 put_user이며 실패하면 EFAULT입니다. Kernel pointer 계산이 맞아도 사용자 메모리 접근은 별도로 실패할 수 있습니다.'),detail('정렬','FLAT_STACK_ALIGN에 맞춰 stack_len을 올립니다. 필요한 byte 수와 ABI가 허용하는 stack pointer alignment를 분리해 계산하세요.')])
    topic('ELF FDPIC·Load Map과 Interpreter Entry','프로세스','fs/binfmt_elf_fdpic.c','load_elf_fdpic_binary',
      'FDPIC executable은 segment의 실제 load 위치와 ABI에 필요한 load map을 함께 전달하는 실행 형식입니다.',
      'Loader는 ELF 및 FDPIC 조건·program headers·interpreter 경로를 검증합니다. MMU에서는 non-FDPIC을 일반 loader로 넘기고 NOMMU의 non-FDPIC은 ET_DYN 조건을 봅니다. begin_new_exec 뒤 새 이미지·stack·executable/interpreter mapping·load map tables를 준비합니다. 시작 주소는 interpreter entry가 있으면 그것, 아니면 executable entry이며 오류 정리에서 file과 할당한 map/header를 해제합니다.',
      '지원 ABI의 고정 source와 Documentation을 따라 PT_LOAD·PT_INTERP·FDPIC loadmap을 비교합니다. 일반 ELF section 분석과 실행 segment 배치를 구분하고, 이 loader가 모든 architecture에서 사용되는 것이 아니라 config/ABI 조건을 가진다는 점을 확인합니다.',
      'load_elf_fdpic_binary의 begin_new_exec·elf_fdpic_map_file·create tables·entryaddr를 읽으세요.',
      q('Interpreter entry가 nonzero이면 start_thread의 entry는?', 'interpreter entry', '항상 main executable entry', 'interp_params.entry_addr ?: exec_params.entry_addr를 사용합니다. Dynamic loader가 실행 준비를 먼저 수행할 수 있는 연결입니다.'),
      q('begin_new_exec 이후 실패는 옛 실행 이미지로 단순 되돌릴 수 있는가?','옛 userspace image가 이미 교체된 경계다','언제나 옛 stack과 code로 복귀한다','원문은 해당 경계 뒤 old userspace image가 사라졌다고 설명합니다. Exec 오류 처리와 일반 reversible 설정 실패를 같은 것으로 보지 않습니다.'),
      details=[detail('Interpreter 입력 검증','PT_INTERP 길이는 PATH_MAX·최소 길이를 확인하고 파일에서 정확한 byte 수를 읽으며 마지막 NUL도 검사합니다. Format field를 신뢰해 임의 길이 allocation과 string 접근을 하지 않습니다.'),detail('GNU ?:','a ?: b는 a가 nonzero이면 a, 아니면 b를 쓰는 GNU C 확장입니다. Entry·dynamic address 선택의 작은 표현을 이해하면 architecture macro에 넘기는 값을 추적할 수 있습니다.')])
    topic('Eventfd·64bit Counter와 Wait Queue','I/O','fs/eventfd.c','eventfd_read',
      'Event를 file descriptor readiness로 연결하면 epoll 기반 프로그램과 kernel producer가 하나의 알림 인터페이스를 사용할 수 있습니다.',
      'Eventfd read는 최소 u64 buffer를 요구합니다. Counter가 0이고 nonblocking/NOWAIT이면 EAGAIN, 아니면 interruptible wait를 합니다. Counter 소비 helper는 semaphore mode면 1을 읽어 1 감소, 일반 mode면 전체 값을 읽어 0으로 만듭니다. Lock 아래 counter 소비와 writer wakeup을 처리한 뒤 userspace에 값을 copy합니다. Copy 실패가 앞선 counter 소비를 자동 복원하지는 않습니다.',
      'Linux·WSL에서 eventfd를 만드는 작은 C 예제로 write u64·read u64·poll을 비교합니다. EFD_SEMAPHORE와 NONBLOCK mode, 한 알림이 한 payload message를 보존하는 queue와 다르다는 점을 확인합니다.',
      'eventfd_read·eventfd_ctx_do_read·eventfd_signal_mask를 읽으세요.',
      q('Counter=5, 일반 read 성공이면 읽은 값과 남은 값은?','읽은 값 5, 남은 값 0','읽은 값 1, 남은 값 4','일반 mode는 누적 counter 전체를 소비합니다. Semaphore mode의 한 단위 소비와 구분합니다.'),
      q('Counter=0이고 NONBLOCK이면?', 'EAGAIN', '반드시 값 0을 즉시 성공 반환', '대기할 event가 없으면 nonblocking error입니다. Readiness와 숫자 0 payload를 구분합니다.'),
      details=[detail('Wakeup 순서','Counter read 후 기다리는 writer에 EPOLLOUT를 깨웁니다. Poll wait 등록·counter 검사·producer 갱신 순서를 잘못 잡으면 missed wakeup이 생길 수 있어 source의 lock과 긴 설명을 연결합니다.'),detail('Recursion 제한','Kernel signal helper는 current->in_eventfd 재진입을 경고하고 건너뜁니다. Custom waitqueue callback에서 다시 eventfd signal을 호출할 때 defer가 필요한 이유를 확인합니다.')])
    topic('Signalfd·Signal을 Record I/O로 소비','I/O','fs/signalfd.c','signalfd_read_iter',
      '비동기 signal 처리를 event loop의 file read와 연결하면 signal 정보와 I/O readiness를 함께 다룰 수 있습니다.',
      'Read는 buffer 길이를 128byte signalfd_siginfo record 수로 나누며 최소 하나가 없으면 EINVAL입니다. Mask에 맞는 pending signal을 dequeue하고 layout별 정보를 zero-initialized record에 copy합니다. 처음은 blocking일 수 있지만 하나를 읽은 뒤에는 nonblock으로 전환합니다. 여러 record 뒤 실패하면 읽은 total을 우선 반환합니다.',
      'Linux·WSL에서 대상 signal을 해당 thread에서 block한 뒤 signalfd와 poll/epoll을 연결하는 작은 예제를 만듭니다. Signal mask·thread/shared pending·read 소비를 구분하고 SIGKILL/SIGSTOP처럼 차단할 수 없는 signal 조건은 생성 경로에서 확인합니다.',
      'signalfd_read_iter·signalfd_dequeue·signalfd_copyinfo·signalfd_poll을 읽으세요.',
      q('Buffer 300byte면 최대 완전 record 수는?', '2개', '3개', '300/128의 정수 나눗셈은 2입니다. 반환도 완전 record 단위이며 남은 44byte에 절반 record를 만들지 않습니다.'),
      q('한 record를 읽은 뒤 다음 signal이 없으면 추가로 blocking wait하는가?', 'nonblock으로 전환해 현재 total을 반환할 수 있다', 'buffer가 꽉 찰 때까지 반드시 기다린다', '첫 copy 후 nonblock=1입니다. Batch read의 이미 얻은 데이터와 추가 대기의 처리 계약을 읽습니다.'),
      details=[detail('Pending Queue','Poll은 current의 pending과 shared_pending을 siglock 아래 확인합니다. 같은 fd 숫자를 다른 thread에서 읽는 것과 그 thread의 signal context를 분리해 이해합니다.'),detail('부분 성공 반환','끝은 total?total:ret입니다. 먼저 읽은 record가 있으면 뒤의 EAGAIN/error보다 성공 byte 수를 우선하는 일반 I/O 계약 사례입니다.')])
    topic('Timerfd·만료 횟수와 주기 재설정','I/O','fs/timerfd.c','timerfd_read_iter',
      'Timer 알림을 fd에 연결해도 만료 횟수·clock 종류·시간 변경 취소를 따로 이해해야 합니다.',
      'Read는 최소 u64 buffer를 요구하고 ticks가 준비될 때까지 기다리거나 nonblocking EAGAIN 경로를 사용합니다. 취소된 clock 상태면 ticks/expired를 지우고 ECANCELED입니다. 만료된 periodic timer는 read에서 forward_now로 지나간 횟수를 반영하고 재시작하며 누적 ticks를 소비합니다. 매우 짧은 주기의 callback 폭주를 피하려고 재설정을 read 경로에서 처리한다는 주석이 있습니다.',
      'Linux·WSL에서 timerfd_create/settime 후 epoll과 u64 read를 연결해 지연 read의 누적 만료를 비교합니다. CLOCK_MONOTONIC/REALTIME·absolute time·cancel-on-set 조건을 확인하고 반환값을 경과 초가 아니라 만료 횟수로 해석합니다.',
      'timerfd_read_iter의 timerfd_canceled·tintv·forward_now·ctx->ticks=0을 읽으세요.',
      q('Read로 얻는 u64는 기본적으로 무엇을 뜻하는가?', '누적 timer 만료 횟수', '항상 현재 UTC 초', 'ticks를 copy합니다. Timer 설정의 시간 단위와 read record의 counter 의미를 구분합니다.'),
      q('Periodic timer의 재설정을 source가 callback 대신 read에서 하는 이유는?', '매우 짧은 주기로 callback이 폭주하는 위험을 줄이기 위해', '모든 clock에서 timer를 영구적으로 끄기 위해', '원문 주석은 매우 짧은 period의 DoS를 피하기 위한 선택이라고 설명합니다. Callback event와 소비 시 catch-up을 연결합니다.'),
      details=[detail('Readiness','timerfd_poll은 wait queue에 등록하고 ctx->ticks가 있으면 EPOLLIN을 제공합니다. Poll-ready 자체가 timer 값을 읽어 지우는 것은 아닙니다.'),detail('수명 정리','Release는 cancel list에서 제거하고 alarm 또는 hrtimer를 cancel한 뒤 kfree_rcu합니다. Callback이 실행될 수 있는 객체를 바로 free하지 않는 이유를 확인하세요.')])
    topic('Anonymous Inode·FD 기능과 File Operations','I/O','fs/anon_inodes.c','anon_inode_getfile',
      '모든 fd가 디스크 파일 경로를 나타내지는 않습니다. Eventfd 같은 기능도 file operation 인터페이스로 제공할 수 있습니다.',
      'anon_inode_getfile은 공용 anonymous inode를 사용하여 pseudo file을 만듭니다. 내부 helper는 fops owner module 참조를 확보하고 inode 참조 및 file allocation을 처리하며 private_data를 설정합니다. 보통 공용 inode를 공유하지만 secure inode 생성 경로도 있습니다. 반환은 struct file pointer 또는 ERR_PTR이고 이 함수 자체가 userspace fd 번호를 설치하는 것은 아닙니다.',
      '고정 source에서 eventfd/timerfd의 file_operations와 anonymous file 생성·fd 설치 경로를 연결합니다. Inode 공유가 private_data 공유를 뜻하지 않으며 /proc/PID/fd의 표시 이름과 디스크 경로를 구분합니다.',
      'anon_inode_getfile·__anon_inode_getfile의 try_module_get·ihold·alloc_file_pseudo·private_data를 읽으세요.',
      q('반환값은 바로 userspace fd 정수인가?', 'file 객체 pointer 또는 error pointer', '항상 작은 fd 정수', '함수 반환형은 struct file*입니다. get_unused_fd_flags/fd_install을 사용하는 상위 fd 생성 경로는 별도입니다.'),
      q('공용 inode를 공유하면 모든 file의 private_data도 같은가?', '각 file에 caller가 준 private_data를 설정한다', '반드시 전역 하나의 상태만 공유한다', 'file->private_data=priv입니다. Inode의 종류·참조와 열린 file별 상태를 구분합니다.'),
      details=[detail('오류 해제','File allocation 실패는 iput 후 module_put으로 이어집니다. 성공 객체가 사용하는 참조와 실패 rollback의 균형을 표시하세요.'),detail('보안 Inode','make_inode=true인 경로는 anon_inode_make_secure_inode를 사용합니다. 공용 inode를 쓰는 wrapper 설명을 모든 anonymous fd 보안 경로에 일반화하지 않습니다.')])
    topic('PIDFS·PID 객체를 File 참조로 연결','프로세스','fs/pidfs.c','pidfs_alloc_file',
      '프로세스 숫자만 보관하면 종료 뒤 재사용된 PID와 혼동할 수 있어 객체 참조를 가진 fd 인터페이스가 필요합니다.',
      'PIDFS alloc은 get_pid로 PID 객체 참조를 얻어 stashed path 생성에 전달합니다. 실패는 ERR_PTR이고 성공 path는 dentry_open으로 file에 연결한 뒤 path_put합니다. PID 객체의 수명과 열린 file의 참조를 통해 숫자 재사용과 객체 identity를 구분하는 경로입니다. PID 참조를 가진다고 해당 프로세스가 계속 실행 중이라는 보장은 아닙니다.',
      'Linux·WSL의 지원 kernel에서 pidfd_open·poll과 PID 종료를 작은 예제로 관찰하고 고정 source의 pidfd file operations 및 pidfs path helper를 연결합니다. PID number·struct pid·task_struct·살아 있는 process 상태를 구분합니다.',
      'pidfs_alloc_file의 get_pid·path_from_stashed·dentry_open·path_put을 읽으세요.',
      q('PID 객체 참조가 남으면 프로세스 실행도 반드시 계속되는가?', '객체 수명과 실행 상태는 다르다', '참조가 있으면 종료를 할 수 없다', 'Identity 보존과 task 실행은 다른 조건입니다. 열린 pidfd로 종료 상태를 관찰할 수 있는 원리를 연결합니다.'),
      q('dentry_open 뒤 local path는 어떻게 처리하는가?', 'path_put으로 해당 참조를 정리한다', 'file이 있으면 local path 참조도 무조건 누적한다', '함수는 path_put 후 pidfd_file을 반환합니다. File과 temporary path의 참조 소유를 따로 추적합니다.'),
      details=[detail('ERR_PTR','Pointer 반환 API는 음수 errno를 error pointer로 표현할 수 있습니다. IS_ERR/PTR_ERR를 확인하기 전에 file field를 dereference하지 않습니다.'),detail('권한과 기능','객체를 가리키는 fd가 있다고 모든 signal/정보 조회 권한을 얻는 것은 아닙니다. 각 pidfd operation의 credential·namespace 검사까지 이어 읽습니다.')])
    topic('POSIX ACL·Named Entry와 Mask 권한','파일시스템','fs/posix_acl.c','posix_acl_permission',
      'Owner/group/other 세 비트 외에 특정 사용자·그룹 권한을 제공하려면 entry 순서와 mask의 제한을 이해해야 합니다.',
      '검사는 requested read/write/execute bit로 want를 제한하고 owner·named user·group entries를 순회합니다. Named user와 맞는 group 권한에는 ACL_MASK가 제한으로 적용됩니다. Owner는 직접 권한을 검사합니다. 맞는 group을 찾았지만 필요한 권한을 얻지 못하면 OTHER로 우회하지 않고 EACCES입니다. UID/GID 비교에는 mount idmap과 filesystem user namespace 변환을 사용합니다.',
      '격리된 임시 디렉터리에서 getfacl/setfacl로 named user·mask의 effective 권한을 비교합니다. Owner와 named user, group class mask의 차이를 확인하고 전체 접근 결정의 capability·LSM·read-only mount 조건과 ACL 함수의 범위를 구분합니다.',
      'posix_acl_permission의 make_vfsuid·found·ACL_OTHER·mask label을 읽으세요.',
      q('Named user r/w 권한과 mask r만 있을 때 write 요청은?', 'EACCES', 'named user가 있으므로 무조건 허용', 'entry permission AND mask AND want가 want와 같아야 합니다. Mask가 write를 제거하므로 필요한 bit가 부족합니다.'),
      q('맞는 group은 있지만 필요한 권한이 부족하면 OTHER 권한으로 자동 허용하는가?', 'found이면 OTHER에서 EACCES다', '항상 OTHER의 더 넓은 권한을 추가한다', 'ACL_OTHER branch에서 found면 EACCES입니다. 서로 다른 접근 범주의 권한을 무조건 합산하지 않습니다.'),
      details=[detail('Idmap 비교','Mount idmap과 inode user namespace를 거쳐 VFS UID/GID로 비교합니다. 디스크 저장 UID 정수와 현재 task credential을 변환 없이 같은 숫자라고 가정하지 않습니다.'),detail('함수 범위','이 함수의 성공 0은 ACL 검사 결과입니다. 파일 전체 접근 정책에는 VFS와 LSM 등 다른 검사도 있어 성공값만으로 모든 operation 허용을 결론내리지 않습니다.')])
    topic('Iomap Iterator·Range 진행과 Stale 재매핑','파일시스템','fs/iomap/iter.c','iomap_iter',
      '여러 파일시스템의 extent 매핑을 공통 I/O 코드에서 쓰려면 begin/end callback과 처리한 길이 계약이 필요합니다.',
      'Iterator는 이전 iomap을 end callback으로 마무리하고 processed만큼 pos를 늘리고 len을 줄입니다. 음수 processed는 오류, 0은 정상 종료지만 STALE이면 진행 없이 재매핑할 수 있습니다. 처리 길이가 현재 iomap 범위를 넘으면 EIO입니다. 다음 begin으로 dst/source mapping을 얻고 1을 반환하면 caller가 loop body를 수행합니다. 0 또는 음수 뒤 loop body를 다시 실행하면 안 됩니다.',
      '고정 source의 iomap_iter를 사용하는 buffered/direct I/O나 seek를 연결하고 processed·pos·len을 표로 추적합니다. 한 extent 길이와 요청 남은 길이를 구분하며 stale map의 remap 및 begin/end cleanup 계약을 확인합니다.',
      'iomap_iter·iomap_iter_advance·iomap_iter_done의 processed·STALE를 읽으세요.',
      q('pos=100, len=60에서 processed=20이면 다음 범위는?', 'pos=120, len=40', 'pos=80, len=80', '완료량을 시작 위치에 더하고 남은 길이에서 뺍니다. Extent 길이 전체를 무조건 소비하는 것이 아닙니다.'),
      q('processed=0이면 STALE map도 반드시 종료하는가?', 'STALE이면 남은 범위를 재매핑할 수 있다', '0은 모든 상태에서 무조건 EOF다', '진행 helper는 !processed&&!stale일 때 종료합니다. 동시 extent 변경을 나타내는 stale flag의 예외를 연결합니다.'),
      details=[detail('End 오류와 진행','iomap_end의 음수 반환은 !processed일 때 즉시 반환합니다. 이미 처리한 길이와 cleanup 오류의 계약을 source 조건 그대로 추적합니다.'),detail('Mapping 불변식','done은 offset<=pos, length>0, mapping 끝>pos 및 stale 없음 조건을 WARN으로 검사합니다. 경고가 반드시 함수의 error 반환으로 바뀌는 것은 아닙니다.'),detail('전체 파일','파일은 advance·done·public iter 세 함수와 trace/include로 구성됩니다. Advance의 상태 초기화는 iomap과 srcmap을 0으로 지워 다음 callback 결과와 이전 상태가 섞이지 않게 합니다.')])
    topic('Iomap Seek·Sparse Hole과 Unwritten 범위','파일시스템','fs/iomap/seek.c','iomap_seek_data',
      'Sparse 파일에서 zero byte 내용과 실제 hole·unwritten mapping의 차이를 알아야 SEEK_DATA/HOLE 의미를 해석할 수 있습니다.',
      'Seek wrapper는 음수 또는 EOF 이상 위치를 ENXIO로 거부하고 IOMAP_REPORT로 남은 범위를 순회합니다. DATA 탐색은 HOLE을 건너뛰고 mapped data를 찾으면 진행을 멈춥니다. UNWRITTEN은 page cache의 hole/data helper를 추가 조회합니다. DATA를 끝까지 못 찾으면 ENXIO지만 HOLE 탐색이 끝에 도달하면 EOF size를 반환합니다.',
      '격리된 임시 sparse 파일에서 lseek SEEK_DATA/SEEK_HOLE 결과와 fiemap을 비교합니다. 내용이 모두 0인 allocated extent를 자동 hole로 단정하지 않고 filesystem 지원·unwritten/pagecache 처리와 EOF 경계를 확인합니다.',
      'iomap_seek_data/hole과 두 iter helper의 UNWRITTEN·HOLE 분기를 읽으세요.',
      q('size=1000, SEEK_DATA pos=1000이면?', 'ENXIO', '항상 1000 성공', 'wrapper는 pos>=size를 거부합니다. 마지막 data 이후 탐색 결과와 EOF 경계 요청을 구분합니다.'),
      q('유효 pos에서 마지막까지 hole이 없으면 SEEK_HOLE 결과는?', 'size인 EOF', '반드시 ENXIO만 반환', 'hole wrapper는 iteration이 끝나면 size를 반환합니다. data wrapper의 못 찾은 ENXIO와 다릅니다.'),
      details=[detail('Unwritten','UNWRITTEN은 할당 상태와 아직 기록되지 않은 의미를 가진 범위입니다. Source는 mapping_seek_hole_data로 pagecache 정보를 함께 보므로 물리 extent type 하나만으로 모든 seek 결과를 고정하지 않습니다.'),detail('전체 파일','두 iter helper와 두 public wrapper가 DATA/HOLE 탐색의 대칭과 차이를 만듭니다. Includes 및 두 GPL export는 filesystem이 이 공통 seek 경로를 연결하도록 합니다.')])
    topic('Iomap FIEMAP·Extent 상태와 마지막 Record','파일시스템','fs/iomap/fiemap.c','iomap_fiemap',
      '파일 logical range의 물리 매핑을 조회할 때 address뿐 아니라 delalloc·unwritten·inline·shared 상태도 필요합니다.',
      'FIEMAP은 report iterator로 extent를 순회하고 hole은 출력하지 않습니다. DELALLOC에는 UNKNOWN/DELALLOC, UNWRITTEN에는 UNWRITTEN, INLINE에는 DATA_INLINE flag를 추가하며 shared/merged도 전달합니다. Prev mapping을 보관해 다음 mapping을 만날 때 출력하고 마지막에 LAST flag를 붙입니다. 출력 배열이 가득 차면 processed=0으로 중단합니다.',
      '격리된 임시 파일에서 filefrag 같은 조회 도구와 FIEMAP ioctl의 extent flag를 비교합니다. Delayed allocation에 physical address가 아직 확정되지 않을 수 있고 shared extent는 독점 block이 아니므로 주소 목록만으로 의미를 단정하지 않습니다.',
      'iomap_fiemap·iomap_fiemap_iter·iomap_to_fiemap의 prev·LAST·flags를 읽으세요.',
      q('DELAYED allocation mapping의 physical address는 항상 확정 상태인가?', 'UNKNOWN/DELALLOC 상태로 보고할 수 있다', '무조건 최종 디스크 주소다', 'IOMAP_DELALLOC은 FIEMAP_EXTENT_DELALLOC|UNKNOWN을 추가합니다. 할당 예약과 확정 물리 위치를 구분합니다.'),
      q('출력 extent 배열이 가득 차면 무한히 다음 entry를 쓰는가?', 'iterator의 진행을 0으로 만들어 중단한다', 'capacity를 무시하고 계속 기록한다', 'iomap_to_fiemap 반환 1은 extent array full이며 iter helper가 0을 반환합니다. Capacity와 iteration 종료의 연결입니다.'),
      details=[detail('Prev 유지','다음 extent를 읽을 때 이전 extent를 내보내는 이유는 마지막 mapping에 LAST를 붙이기 위해서입니다. 하나 뒤로 미뤄 출력하는 상태 저장 알고리즘입니다.'),detail('Bmap과 반환 계약','같은 파일의 legacy iomap_bmap은 오류에 0을 사용하는 API라고 주석으로 명시합니다. FIEMAP의 errno 반환과 block 번호 반환을 같은 방식으로 처리하지 않습니다.')])
